package tools

import (
	"encoding/json"
	"os"
	"sort"
	"testing"
)

// Golden parity test: internal/tools/testdata/markdown_golden.json was
// generated by executing the REAL upstream
// @a-bonus/google-docs-mcp@1.11.3 convertMarkdownToRequests (via node, no
// network) over testdata/markdown_corpus.json. The Go port must produce the
// byte-identical request array (JSON.stringify of the JS objects, key order
// included) for every corpus case not on the known-divergence list.

type corpusCase struct {
	Name                string `json:"name"`
	Markdown            string `json:"markdown"`
	StartIndex          int    `json:"startIndex"`
	TabID               string `json:"tabId"`
	FirstHeadingAsTitle bool   `json:"firstHeadingAsTitle"`
}

type goldenCase struct {
	OK       bool              `json:"ok"`
	Requests []json.RawMessage `json:"requests"`
	Error    string            `json:"error"`
}

// knownDivergences documents inputs where the Go port's request stream is
// known to differ from upstream markdown-it behavior. Each entry must name
// the mechanism. Everything not listed must match byte-for-byte.
var knownDivergences = map[string]string{}

func normalizeRequests(reqs []json.RawMessage) []string {
	out := make([]string, 0, len(reqs))
	for _, r := range reqs {
		out = append(out, string(r))
	}
	return out
}

func TestConvertMarkdownToRequests_Golden(t *testing.T) {
	corpusRaw, err := os.ReadFile("testdata/markdown_corpus.json")
	if err != nil {
		t.Fatal(err)
	}
	goldenRaw, err := os.ReadFile("testdata/markdown_golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var corpus []corpusCase
	if err := json.Unmarshal(corpusRaw, &corpus); err != nil {
		t.Fatal(err)
	}
	var golden map[string]goldenCase
	if err := json.Unmarshal(goldenRaw, &golden); err != nil {
		t.Fatal(err)
	}
	for _, c := range corpus {
		t.Run(c.Name, func(t *testing.T) {
			gc, ok := golden[c.Name]
			if !ok {
				t.Fatalf("no golden for %s", c.Name)
			}
			startIndex := c.StartIndex
			if startIndex == 0 {
				startIndex = 1
			}
			reqs, err := convertMarkdownToRequests(c.Markdown, startIndex, c.TabID, c.FirstHeadingAsTitle)
			if _, known := knownDivergences[c.Name]; known {
				t.Skipf("known divergence: %s", knownDivergences[c.Name])
			}
			if err != nil {
				if gc.OK {
					t.Fatalf("go error %v, upstream ok", err)
				}
				return // both errored
			}
			if !gc.OK {
				t.Fatalf("upstream error %q, go ok with %d requests", gc.Error, len(reqs))
			}
			got := normalizeRequests(reqs)
			want := normalizeRequests(gc.Requests)
			if len(got) != len(want) {
				t.Fatalf("request count: got %d want %d\ngot:  %v\nwant: %v", len(got), len(want), got, want)
			}
			for i := range got {
				if got[i] != want[i] {
					t.Errorf("request %d:\n got: %s\nwant: %s", i, got[i], want[i])
				}
			}
		})
	}
}

// TestKnownDivergencesCurrent keeps the divergence list honest: if a listed
// case starts matching upstream, the list must be updated.
func TestKnownDivergencesCurrent(t *testing.T) {
	if len(knownDivergences) == 0 {
		return
	}
	names := make([]string, 0, len(knownDivergences))
	for k := range knownDivergences {
		names = append(names, k)
	}
	sort.Strings(names)
	t.Logf("divergences: %v", names)
}
